svg.script:
{
  "metadata": {"title": "Kanban Board", "projectName": "Food Delivery System", "description": "Task workflow visualization with columns and cards", "version": "1.0", "mode": "light"},
  "config": {"layout": {"canvasWidth": 1920, "canvasHeight": 1080}, "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#FFFFFF", "strokeColor": "#334155", "columnColor": "#f1f5f9"}},
  "data": {
    "columns": [
      {"id": "col1", "name": "Backlog", "x": 120, "y": 150, "width": 380, "height": 850},
      {"id": "col2", "name": "To Do", "x": 540, "y": 150, "width": 380, "height": 850},
      {"id": "col3", "name": "In Progress", "x": 960, "y": 150, "width": 380, "height": 850},
      {"id": "col4", "name": "Done", "x": 1380, "y": 150, "width": 380, "height": 850}
    ],
    "cards": [
      {"id": "c1", "column": "col1", "title": "Task 1", "priority": "high"},
      {"id": "c2", "column": "col1", "title": "Task 2", "priority": "medium"},
      {"id": "c3", "column": "col2", "title": "Task 3", "priority": "high"},
      {"id": "c4", "column": "col3", "title": "Task 4", "priority": "medium"},
      {"id": "c5", "column": "col4", "title": "Task 5", "priority": "low"}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#kanban-board-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Kanban Board Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Kanban Board] Invalid JSON:', e.message);
  }
})();
